void Solver::restart() {
    // Aggressively reset LBD statistics
    fast_lbd_sum = 0;
    lbd_queue_size = 0;
    lbd_queue_pos = 0;
    // Backtrack to root level
    backtrack(0);
    // Rephase variables with mixed strategy
    int r = rand() % 100;
    if (r < 50) {
        // 50% keep the best phase seen so far
        for (int i = 1; i <= vars; ++i) saved[i] = local_best[i];
    } else if (r < 70) {
        // 20% invert the best phase
        for (int i = 1; i <= vars; ++i) saved[i] = -local_best[i];
    } else if (r < 90) {
        // 20% assign random phase
        for (int i = 1; i <= vars; ++i) saved[i] = (rand() & 1) ? 1 : -1;
    } else {
        // 10% keep previous saved phase (no change)
        // do nothing
    }
    // Decay activity scores to diversify future decisions
    var_inc *= 0.5;
    for (int i = 1; i <= vars; ++i) {
        activity[i] *= 0.5;
        if (!vsids.inHeap(i)) vsids.insert(i);
    }
}

